export const PERMIT_ADD_DRAFT_KEY = 'PRESALE_PERMIT_ADD_DRAFT'

/** 申请页跳转方案维护页前的楼幢/表单快照（新增与编辑态共用） */
export const PERMIT_PLAN_NAV_DRAFT_KEY = 'PRESALE_PERMIT_PLAN_NAV_DRAFT'

/** 从方案维护页返回申请页时，路由 query 标记（与 sessionStorage 快照配合） */
export const PERMIT_PLAN_NAV_RESTORE_QUERY = 'restorePlanNav'

/** 构造申请页返回路由（hash 模式下保证 query 合法） */
export function buildPermitApplyReturnRoute(route, { restore = true } = {}) {
  const query = { ...(route?.query || {}) }
  if (restore) {
    query[PERMIT_PLAN_NAV_RESTORE_QUERY] = '1'
  } else {
    delete query[PERMIT_PLAN_NAV_RESTORE_QUERY]
  }
  return {
    path: route?.path || '',
    query
  }
}

/** 方案维护页 handleBack 使用的 fullPath */
export function buildPermitApplyReturnPath(route, options) {
  const resolved = router.resolve(buildPermitApplyReturnRoute(route, options))
  return resolved.route?.fullPath || resolved.href || route?.fullPath || route?.path || '/'
}

export function shouldRestorePermitPlanNav(route) {
  return String(route?.query?.[PERMIT_PLAN_NAV_RESTORE_QUERY]) === '1'
}

