/** 跳转方案维护页前暂存申请页快照（新增/编辑态共用） */
savePlanNavDraft() {
  const payload = {
    formMode: this.formMode,
    form: this.form,
    selectedBuildings: this.selectedBuildings,
    applyAttachGroupId: this.applyAttachGroupId,
    planAttachGroupId: this.planAttachGroupId
  }
  sessionStorage.setItem(PERMIT_PLAN_NAV_DRAFT_KEY, JSON.stringify(payload))
  if (this.formMode === 'add') {
    sessionStorage.setItem(PERMIT_ADD_DRAFT_KEY, JSON.stringify(payload))
  }
},
/** 从方案维护页返回时恢复申请页快照 */
tryRestorePlanNavDraft() {
  if (!shouldRestorePermitPlanNav(this.$route)) return
  const draft = this.readPlanNavDraft()
  if (!draft) {
    this.clearPlanNavRestoreQuery()
    return
  }
  if (this.formMode === 'add' && draft.form) {
    this.form = { ...createForm(), ...draft.form }
  }
  if (Array.isArray(draft.selectedBuildings)) {
    this.selectedBuildings = draft.selectedBuildings
    if (this.formMode === 'edit') {
      this.pendingPlanNavBuildingSnapshot = draft.selectedBuildings
    }
  }
  if (draft.applyAttachGroupId) {
    this.applyAttachGroupId = draft.applyAttachGroupId
  }
  if (draft.planAttachGroupId) {
    this.planAttachGroupId = draft.planAttachGroupId
  }
  sessionStorage.removeItem(PERMIT_PLAN_NAV_DRAFT_KEY)
  sessionStorage.removeItem(PERMIT_ADD_DRAFT_KEY)
  this.clearPlanNavRestoreQuery()
},
readPlanNavDraft() {
  const keys = [PERMIT_PLAN_NAV_DRAFT_KEY, PERMIT_ADD_DRAFT_KEY]
  for (const key of keys) {
    try {
      const draft = JSON.parse(sessionStorage.getItem(key) || 'null')
      if (draft && typeof draft === 'object') {
        return draft
      }
    } catch (e) {
      /* ignore parse error */
    }
  }
  return null
},
clearPlanNavRestoreQuery() {
  if (!shouldRestorePermitPlanNav(this.$route)) return
  const query = { ...(this.$route.query || {}) }
  delete query[PERMIT_PLAN_NAV_RESTORE_QUERY]
  delete query.restore
  this.$router.replace({ path: this.$route.path, query }).catch(() => {})
},
